function ivParse(text){
  var lines=String(text).replace(/\r/g,'').split('\n').map(function(s){ return s.trim(); }).filter(Boolean);
  if(!lines.length) return { value:null, error:'没有区间' };
  var out=[];
  for(var i=0;i<lines.length;i++){
    var m=lines[i].split(/[,\-~\s]+/).filter(Boolean);
    if(m.length!==2) return { value:null, error:'第 '+(i+1)+' 行格式错误（需 start,end）' };
    var a=Number(m[0]), b=Number(m[1]);
    if(!isFinite(a)||!isFinite(b)) return { value:null, error:'第 '+(i+1)+' 行不是数字' };
    if(a>b) return { value:null, error:'第 '+(i+1)+' 行 start > end' };
    out.push([a,b]);
  }
  return { value:out, error:null };
}
function ivMerge(intervals){
  if(!Array.isArray(intervals)||!intervals.length) return { value:[], error:null };
  var s=intervals.slice().sort(function(a,b){ return a[0]-b[0]||a[1]-b[1]; });
  var out=[[s[0][0],s[0][1]]];
  for(var i=1;i<s.length;i++){
    var last=out[out.length-1];
    if(s[i][0]<=last[1]) last[1]=Math.max(last[1],s[i][1]);
    else out.push([s[i][0],s[i][1]]);
  }
  return { value:out, error:null };
}
function ivIntersect(a,b){
  var lo=Math.max(a[0],b[0]), hi=Math.min(a[1],b[1]);
  if(lo>hi) return null;
  return [lo,hi];
}
function ivSchedule(intervals){
  if(!intervals.length) return { value:{ count:0, picked:[] }, error:null };
  var s=intervals.slice().sort(function(a,b){ return a[1]-b[1]; });
  var picked=[], lastEnd=-Infinity;
  for(var i=0;i<s.length;i++){
    if(s[i][0]>=lastEnd){ picked.push(s[i]); lastEnd=s[i][1]; }
  }
  return { value:{ count:picked.length, picked:picked }, error:null };
}
function ivRooms(intervals){
  if(!intervals.length) return { value:0, error:null };
  var evs=[];
  for(var i=0;i<intervals.length;i++){ evs.push([intervals[i][0],1]); evs.push([intervals[i][1],-1]); }
  evs.sort(function(a,b){ return a[0]-b[0]||a[1]-b[1]; }); // end(-1) before start(+1) at same time
  var cur=0, max=0;
  for(var j=0;j<evs.length;j++){ cur+=evs[j][1]; if(cur>max) max=cur; }
  return { value:max, error:null };
}
function ivGaps(intervals){
  var m=ivMerge(intervals).value;
  var out=[];
  for(var i=1;i<m.length;i++){
    if(m[i][0]>m[i-1][1]) out.push([m[i-1][1],m[i][0]]);
  }
  return { value:out, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { ivParse:ivParse, ivMerge:ivMerge, ivIntersect:ivIntersect,
    ivSchedule:ivSchedule, ivRooms:ivRooms, ivGaps:ivGaps };
}
if (typeof window !== 'undefined') {
  window.IntervalForgePure = { ivParse:ivParse, ivMerge:ivMerge, ivIntersect:ivIntersect,
    ivSchedule:ivSchedule, ivRooms:ivRooms, ivGaps:ivGaps };
}
